theorem measure_finset_sup_ge_le_sum {ι : Type*} {μ : Measure Ω}
    {X : ι → Ω → ℝ} {u : ℝ} {s : Finset ι} (hs : s.Nonempty) :
    μ {ω | u ≤ s.sup' hs (fun i => X i ω)} ≤ ∑ i ∈ s, μ {ω | u ≤ X i ω}

lemma abs_denseRestriction_le
